import sys; sys.path.insert(0,'.')
from ftclient import jcall

min_ep = 64
min_loc = None
count_zero = 0
for p in range(10):
    for ch in range(14):
        for row in range(64):
            c = jcall("pattern_get_cell", pattern=p, row=row, channel=ch)
            if c.get('instrument'):
                ep = c['effect_param'] if c['effect']==12 else None
                if ep is not None:
                    if ep == 0:
                        count_zero += 1
                        print("ZERO VOLUME NOTE FOUND:", p, row, ch, c)
                    if ep < min_ep:
                        min_ep = ep
                        min_loc = (p, row, ch, c)
print("minimum effective volume found:", min_ep, "at", min_loc)
print("count of zero-volume notes:", count_zero)
EOF
